  "setSubject": "통합(생식의학·산과 마취·흉부 해부)",
  "subtopic": "부인과 — 골반통·부인과 해부·자궁외임신",
  "type": "부인과 — 골반통·부인과 해부·자궁외임신",
  "modality": "",
